path='/tmp/llm_rollout_iye76rwp/sheetpedia_batch1_0029_double_counting_8811_input.xlsx'
wb=openpyxl.load_workbook(path, data_only=False)
# Look for formulas with SUM where a reference appears multiple times or ranges overlap
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for c in row:
            if c.value is not None and isinstance(c.value, str) and c.value.startswith('='):
                v=c.value.upper()
                if 'SUM(' in v:
                    # extract args inside SUM(...)
                    m=re.search(r'SUM\((.*)\)', v, re.S)
                    if m:
                        args=m.group(1)
                        print(ws.title, c.coordinate, '=>', args)
